/**
 * Hall das Lendas — carreiras reais curadas (50 lendas do futebol masculino).
 *
 * Números de CARREIRA em jogos OFICIAIS (clubes + seleção principal; amistosos de clube e base fora).
 * Pesquisados e conferidos em duas fontes por lenda em out/2026 (MessivsRonaldo.app, Wikipedia
 * en/pt/es/it/de, Transfermarkt jogo a jogo, RSSSF, sites oficiais de clubes e federações). As URLs
 * ficam em `sources`. Regras de contagem:
 *   - apps/goals: clube + seleção principal, com os amistosos da seleção principal (jogos "A"). Times B,
 *     reservas, seleções de base, Olimpíada e jogos indoor não contam. Para jogadores antigos as bases
 *     divergem; o valor é o mais bem documentado e o campo vai em `uncertain`.
 *   - assists: só existem registros confiáveis de ~2000 em diante (Messi e Cristiano: MessivsRonaldo.app;
 *     os demais: Transfermarkt). Sem registro, é uma ESTIMATIVA arredondada (`assistsEstimated: true`)
 *     — a UI mostra "≈".
 *   - ballonDor: Bola de Ouro da France Football (inclui a edição FIFA 2010–2015). Antes de 1995 só
 *     europeus eram elegíveis (Pelé, Maradona, Zico, Garrincha… têm 0 oficial; prêmios honorários
 *     ficam em `notes`).
 *   - goldenBoots: Chuteira de Ouro EUROPEIA (desde 1968).
 *   - ucl: Copa dos Campeões / Champions League. libertadores: Copa Libertadores.
 *   - leagueTitles: campeonatos nacionais de PRIMEIRA divisão (qualquer país; Apertura e Clausura
 *     contam separados; títulos revogados não contam; estaduais não contam). Títulos de playoff (NASL
 *     Soccer Bowl, MLS Cup) contam como título nacional; o Supporters' Shield da MLS fica só no total.
 *   - otherMajorTitles: outros títulos oficiais grandes — Copa América/Euro, Mundial de Clubes /
 *     Intercontinental, segunda copa continental (Copa da UEFA/Liga Europa, Recopa Europeia,
 *     Sul-Americana/Mercosul/Supercopa) e ouro olímpico. Supercopas, Liga das Nações, Copa das
 *     Confederações e Finalíssima ficam de fora (mas entram em `totalTitles`).
 *   - totalTitles: TODOS os títulos oficiais coletivos de clube e de seleção principal (ligas, copas,
 *     supercopas, estaduais, continentais, mundiais, Copa do Mundo…), a soma de `honours[].n`. Ficam
 *     fora amistosos e torneios de convite (Gamper, Copa Roca…), turnos (Taça Guanabara), base e
 *     títulos em que o jogador não jogou nem estava na lista do jogo (Supercopa da Espanha 2005 do
 *     Messi, Community Shield 2008 do Cristiano…). Por isso pode dar menos que a conta do clube.
 *   - Troca no meio da temporada: o título conta para quem jogou partidas oficiais pelo campeão
 *     naquela temporada antes de sair (ex.: Ronaldo 2006/07, Ronaldinho 2010/11, Suárez 2010/11 pelo
 *     Ajax, Tostão no Mineiro 1972).
 *   - retroBallonDor: Bolas de Ouro do "Nouveau Palmarès" da France Football (2016), que reavaliou as
 *     edições em que só europeus concorriam (Pelé 7, Maradona 2, Garrincha 1, Romário 1). NÃO são
 *     oficiais: a Nota de Legado dá 3/4 de crédito a cada uma e a categoria mostra só as oficiais.
 *   - awards: TODOS os prêmios individuais com os anos. `key` diz em que categoria do jogo o prêmio
 *     conta — as mesmas que uma carreira do jogo ganha (AwardId):
 *       the_best .............. Melhor do Mundo da FIFA (FIFA World Player 1991–2009 e The Best desde
 *                               2016; os FIFA Ballon d'Or 2010–15 ficam só em ballon_dor);
 *       league_best_player .... UM prêmio de melhor jogador de LIGA por temporada (oficial da liga,
 *                               sindicato dos jogadores ou o prêmio de imprensa consagrado daquela liga).
 *                               "Futebolista do ano" do país (Olimpia de Plata, CNID…) é `other`;
 *       league_top_scorer ..... artilharia de uma liga nacional de primeira divisão. Até 1970 o Brasil
 *                               não tinha liga nacional de pontos corridos: a artilharia do estadual (a
 *                               liga que o clube disputava) conta — Pelé no Paulistão, Tostão no Mineiro;
 *       wc_golden_ball / wc_golden_boot ... melhor jogador / artilheiro da Copa (antes de 1982,
 *                               a escolha retroativa que a FIFA credita);
 *       golden_glove .......... melhor goleiro do MUNDO no ano (IFFHS, The Best, Troféu Yashin), um por
 *                               ano. Melhor goleiro de liga, da Champions ou da Copa é `other`;
 *       kopa .................. melhor jovem do mundo/Europa no ano (Kopa, Golden Boy, Bravo);
 *       puskas, ballon_dor, golden_boot ... o próprio prêmio.
 *     `continental_best`, `continental_top_scorer`, `tournament_best`, `tournament_top_scorer` e `other`
 *     aparecem na ficha, mas não contam nas categorias: o jogo não dá esses prêmios, e a régua tem de
 *     ser a mesma para lendas e carreiras.
 *   - records: marcas notáveis curtas (destaques da ficha). `feats` é a lista completa de feitos
 *     verificados. NENHUM dos dois entra na nota: a categoria Recordes usa recordes mundiais
 *     ESTRUTURADOS, nas mesmas métricas que uma run pode quebrar — os atuais
 *     (`HISTORIC_RECORDS[].holderIds`) + `pastRecords` (marcas mundiais que a lenda deteve, sozinha
 *     ou dividida, e perdeu depois).
 *   - uncertain / uncertainAwards: campos e chaves de prêmio com fontes divergentes (a UI mostra "≈");
 *     `doubts` explica cada ponto em aberto.
 *   - Jogadores em atividade: números até o último jogo antes da conferência (`asOf` = 2026-10). No
 *     build do site, Messi e Cristiano Ronaldo podem vir atualizados do MessivsRonaldo.app
 *     (src/data/legendsLive.ts).
 */
import type { AwardId, Position } from '../../engine/types'

export type LegendField = 'apps' | 'goals' | 'assists' | 'ballonDor' | 'worldCups' | 'goldenBoots' | 'ucl' | 'libertadores' | 'leagueTitles' | 'otherMajorTitles' | 'totalTitles'

export interface LegendClub {
  name: string
  /** Id do clube em src/data/generated/game-data.json, quando o clube existe no jogo. */
  clubId?: string
}

/** Grupo de um título na ficha: Seleção, Mundiais, Continentais, Ligas, Copas, Supercopas, Estaduais, Outros. */
export type HonourKind = 'national' | 'world' | 'continental' | 'league' | 'cup' | 'supercup' | 'state' | 'other'

export interface LegendHonour {
  /** "Campeonato Espanhol (La Liga)". */
  name: string
  /** Clube ou seleção. */
  team: string
  n: number
  /** "2004/05, 2005/06…" (texto livre, como nas fontes). */
  years: string
  kind: HonourKind
}

/** Prêmios que o jogo também dá (contam nas categorias). `team_of_the_year` não entra: as seleções do ano são `other`. */
export type LegendGameAwardKey = Exclude<AwardId, 'team_of_the_year'>
/** Chave de um prêmio da lenda: as do jogo contam nas categorias; as demais só aparecem na ficha. */
export type LegendAwardKey = LegendGameAwardKey | 'continental_best' | 'continental_top_scorer' | 'tournament_best' | 'tournament_top_scorer' | 'other'

export interface LegendAward {
  name: string
  n: number
  /** "2009, 2010…" ou "2009/10 (34 gols), …". */
  years: string
  key: LegendAwardKey
}

export interface Legend {
  id: string
  /** Nome de exibição (pt-BR). */
  name: string
  fullName: string
  /** Seleção (código FIFA). URS = União Soviética. */
  nationality: string
  /** Chave de bandeira (flag-icons) quando o código FIFA não existe mais no jogo. */
  flag?: string
  position: Position
  born: number
  /** Estreia profissional e último ano como jogador (null = em atividade). */
  years: [number, number | null]
  active?: boolean
  /** Data de corte dos números de quem ainda joga. */
  asOf?: string
  clubs: LegendClub[]
  apps: number
  goals: number
  assists: number
  assistsEstimated: boolean
  ballonDor: number
  worldCups: number
  goldenBoots: number
  ucl: number
  libertadores: number
  leagueTitles: number
  otherMajorTitles: number
  /** Todos os títulos oficiais coletivos (soma de `honours[].n`). */
  totalTitles: number
  records: string[]
  /** Bolas de Ouro retroativas da France Football (2016) — não oficiais; 3/4 de crédito na nota. */
  retroBallonDor?: number
  /** Recordes MUNDIAIS (métricas do jogo) que a lenda deteve e perdeu depois; os atuais saem de HISTORIC_RECORDS. */
  pastRecords?: LegendRecordMetric[]
  /** Campos com fontes divergentes ou em aberto (a UI mostra "≈"). */
  uncertain?: LegendField[]
  /** Chaves de prêmio com contagem em aberto (a categoria que as soma ganha "≈"). */
  uncertainAwards?: LegendAwardKey[]
  notes?: string[]
  /** Todos os títulos coletivos, um item por competição e equipe. */
  honours: LegendHonour[]
  /** Todos os prêmios individuais, com os anos. */
  awards: LegendAward[]
  /** Feitos e recordes verificados (texto, exibição). */
  feats: string[]
  /** Pontos em aberto nos dados (texto, exibição). */
  doubts?: string[]
  /** Fontes consultadas (URLs). */
  sources: string[]
}

/** Métricas de recorde do motor de legado (src/engine/legacy/records.ts) — as runs quebram as mesmas. */
export type LegendRecordMetric =
  | 'ballonDor'
  | 'ballonDorStreak'
  | 'worldCups'
  | 'goldenBoots'
  | 'ucl'
  | 'libertadores'
  | 'leagueTitles'
  | 'titles'
  | 'goals'
  | 'assists'
  | 'apps'
  | 'goalsPerGame'
  | 'seasonGoals'
  | 'seasonAssists'
  | 'clubGoals'
  | 'nationalGoals'
  | 'youngestBallonDor'
  | 'puskas'
  | 'wcGoldenBalls'

/** Corte dos números de quem ainda joga (ano-mês). */
export const LEGENDS_AS_OF = '2026-10'
/** Dia da conferência dos 50 arquivos (segunda fonte). */
export const LEGENDS_CHECKED_AT = '2026-10-14'

const ACTIVE: Pick<Legend, 'active' | 'asOf'> = { active: true, asOf: LEGENDS_AS_OF }
const c = (name: string, clubId?: string): LegendClub => (clubId ? { name, clubId } : { name })
const h = (name: string, team: string, n: number, years: string, kind: HonourKind): LegendHonour => ({ name, team, n, years, kind })
const a = (name: string, n: number, years: string, key: LegendAwardKey): LegendAward => ({ name, n, years, key })

/**
 * Todos os títulos da lenda. Lista no formato antigo (sem `totalTitles`, vinda de JSON ou montada à
 * mão) cai para a soma de `honours[].n`, e sem `honours`, 0 — nunca NaN na nota.
 */
export const legendTotalTitles = (l: Pick<Legend, 'totalTitles' | 'honours'>): number => (Number.isFinite(l.totalTitles) ? l.totalTitles : (l.honours ?? []).reduce((s, x) => s + (Number(x.n) || 0), 0))

