export const LEGEND_BY_ID: Record<string, Legend> = Object.fromEntries(REAL_LEGENDS.map((l) => [l.id, l]))

/**
 * Recordes históricos "absolutos" (alguns de jogadores fora da lista acima). O motor de legado
 * compara as runs com eles; os demais recordes saem do próprio conjunto `REAL_LEGENDS`.
 * `lowerIsBetter` para marcas de idade. Gols, assistências, gols pela seleção e títulos de quem
 * ainda joga acompanham o número da lenda (ver records.ts: o maior entre este valor e o da ficha).
 */
export interface HistoricRecordRef {
  metric: LegendRecordMetric
  value: number
  holder: string
  /** Lendas de REAL_LEGENDS que detêm a marca hoje (contam na categoria Recordes delas). */
  holderIds?: string[]
  /** Complemento exibido: "(2011/12)". */
  detail?: string
  approx?: boolean
  lowerIsBetter?: boolean
}

